<script setup lang="ts">import {computed} from 'vue';import {Result} from '../types/domain';import {number} from '../utils/format';const props=defineProps<{result:Result}>();const hi=computed(()=>Math.max(.01,props.result.statistics.R2,...props.result.statistics.null_R2)*1.04);const bins=computed(()=>{const b=Array(20).fill(0);props.result.statistics.null_R2.forEach(v=>b[Math.min(19,Math.floor(v/hi.value*20))]++);return b});const peak=computed(()=>Math.max(...bins.value));const x=(v:number)=>40+v/hi.value*340;</script><template><section class="permutation-plot"><h3>固定组规模的标签置换零分布</h3><svg viewBox="0 0 420 205" role="img" aria-label="PERMANOVA R平方置换零分布"><rect v-for="(n,i) in bins" :key="i" :x="40+i*17" :y="153-n/peak*105" width="14" :height="n/peak*105"/><line :x1="x(result.statistics.R2)" :x2="x(result.statistics.R2)" y1="30" y2="157"/><text :x="Math.min(320,x(result.statistics.R2))" y="21">观测R²</text><text x="40" y="180">0</text><text x="345" y="180">{{number(hi,3)}}</text></svg><p>p=({{result.statistics.extreme}}+1)/({{result.permutations}}+1)={{number(result.statistics.p,4)}}；上尾比较R²，含并列。最小分辨率{{number(result.statistics.resolution,4)}}。</p></section></template>
